const store = $getWorkflowStaticData("global");
const bootstrap = store.pcBootstrapDone !== true;
store.lastPcScanWasBootstrap = bootstrap;
store.pcBootstrapDone = true;

// Set KLEINANZEIGEN_SEARCH_URL in your n8n environment to point this at a
// different city/category search on kleinanzeigen.de. Grab it by doing a
// search on the site yourself and copying the resulting URL (without the
// "?sortingField=..." part, that gets added automatically).
// Default below = "PCs" category, Wuerzburg +/- 30km.
const defaultUrl = "https://www.kleinanzeigen.de/s-pcs/wuerzburg/c228l7667r30";
const baseUrl = ($env.KLEINANZEIGEN_SEARCH_URL || defaultUrl).replace(/\?.*$/, "").replace(/\/$/, "");
const segments = baseUrl.split("/");
const lastSegment = segments.pop();

function pageUrl(page) {
  const parts = page > 1 ? [...segments, `seite:${page}`, lastSegment] : [...segments, lastSegment];
  return parts.join("/") + "?sortingField=SORTING_DATE";
}

const urls = [pageUrl(1)];
if (bootstrap) urls.push(pageUrl(2), pageUrl(3));

return urls.map((scanUrl, index) => ({json:{scanUrl, page:index + 1, bootstrap}}));

