  if(Array.isArray(rows))return rows.map(r=>r.organicAdPreview).filter(Boolean).map(ad=>({id:String(ad.id||""),url:canonical(ad.seoLink||ad.url||ad.link||""),title:clean(ad.title),description:clean(ad.description),priceText:clean(ad.price),price:price(ad.price),location:[ad.locationName,ad.parentLocationName].filter(Boolean).join(" "),published:clean(ad.sortingDate),image:ad.imageList?.[0]?.xLargeUrl||"",source:"kleinanzeigen.de"})).filter(x=>x.id&&x.url&&x.title);
  const html=typeof raw==="string"?raw:String(raw?.data??raw?.body??raw?.html??""); if(!html||html.length<1000)return [];
  const blocks=[...html.matchAll(/<article\b[\s\S]*?<\/article>/gi)].map(m=>m[0]).filter(b=>/data-adid=/i.test(b));
  return blocks.map(block=>{const id=attr(block,"data-adid"),href=attr(block,"data-href"),title=clean((block.match(/<h2[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/i)||[])[1]),description=clean((block.match(/aditem-main--middle--description[^>]*>([\s\S]*?)<\/p>/i)||[])[1]),priceText=clean((block.match(/aditem-main--middle--price-shipping--price[^>]*>([\s\S]*?)<\/p>/i)||[])[1]);return{id,url:canonical(href),title,description,priceText,price:price(priceText),location:"",published:"",image:attr(block,"src"),source:"kleinanzeigen.de"};}).filter(x=>x.id&&x.url&&x.title);
}
